// Regenerates `anchor-vectors.json`, the ground truth for
// `tests/clients/hashline-anchor.test.ts`.
//
// Everything below the "verbatim port" marker is copied from
// pi-hashline-edit-pro@8f027ca1c2a0796ccf1c15bd5a0d12db5d9fb9f0
// (github.com/YuGiMob/pi-hashline-edit-pro, branch `master`) —
// src/hashline/alphabet.ts, src/hashline/hash.ts, src/hashline/hasher.ts,
// src/utils.ts and src/constants.ts — and it runs against the REAL
// `xxhash-wasm` the extension depends on. That is the point: the fixture is
// generated by the extension's own arithmetic, not by pi-lens's port of it, so
// `clients/hashline-anchor.ts` is pinned against an independent source.
//
// The port covers BOTH hash paths, because both reach pi-lens:
//
// - `_lineHashesPure` — a cold file the extension has no snapshot for.
// - `mapStableHashes` — the path `lineHashes(content, path, {previous})` takes
//   after EVERY edit. It carries a surviving line's old anchor forward and
//   persists the result to the hash store (`src/hash-store.ts`), so those are
//   the anchors the extension SERVES on the next read and the agent sends back
//   in the next tool call. Review round 3 (finding F1): those store-carried
//   anchors are what made pi-lens resolve a drifted anchor to a confident but
//   WRONG line, so the fixture has to contain them.
//
// NOT run by the test suite. `xxhash-wasm` is deliberately not a pi-lens
// dependency (pi installs pi-lens with `npm install --omit=dev`, so a hashing
// dep would ship to every user for one shape adapter). To refresh the table
// after an upstream change:
//
//   npm install xxhash-wasm --no-save
//   node tests/fixtures/hashline-edit-pro/generate-anchor-vectors.mjs \
//     > tests/fixtures/hashline-edit-pro/anchor-vectors.json
//
// then update `upstream.commit` if the pinned commit moved. The output is the
// finished fixture shape — no hand-reshaping step, which is how the commit
// metadata and the vectors stay in one place.
import xxhash from "xxhash-wasm";
const { h32 } = await xxhash();

// --- verbatim port of pi-hashline-edit-pro @ 8f027ca1 (src/hashline/hash.ts) ---
const HASH_LEN = 3;
const ALPH = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
const HASH_SPACE = ALPH.length ** HASH_LEN;
const HASH_PROBE_STRIDE = ALPH.length ** 2 + ALPH.length + 1;
const MAX_HASH_SOURCE_BYTES = 500;
const BITSET_WORDS = Math.ceil(HASH_SPACE / 32);

function splitLines(text) {
  if (text.length === 0) return [""];
  const lines = text.split("\n");
  return text.endsWith("\n") ? lines.slice(0, -1) : lines;
}
function truncateToBytes(s, maxBytes) {
  if (Buffer.byteLength(s, "utf-8") <= maxBytes) return s;
  let out = "";
  let bytes = 0;
  for (const ch of s) {
    const chBytes = Buffer.byteLength(ch, "utf-8");
    if (bytes + chBytes > maxBytes) break;
    out += ch;
    bytes += chBytes;
  }
  return out;
}
function getCached(map, key, compute) {
  if (map.has(key)) return map.get(key);
  const v = compute(key);
  map.set(key, v);
  return v;
}
const canon = (line) => line.replace(/\r/g, "").trimEnd();
const hashSource = (line) => truncateToBytes(canon(line), MAX_HASH_SOURCE_BYTES);
const xxh32 = (input, seed = 0) => h32(input, seed) >>> 0;
function idxToHash(idx) {
  let out = "";
  for (let j = 0; j < HASH_LEN; j++) {
    out = ALPH[idx % ALPH.length] + out;
    idx = Math.floor(idx / ALPH.length);
  }
  return out;
}
const getBit = (bits, idx) => ((bits[idx >>> 5] >>> (idx & 31)) & 1) !== 0;
const setBit = (bits, idx) => {
  bits[idx >>> 5] |= 1 << (idx & 31);
};
function nextZeroBit(bits, start) {
  const totalBits = HASH_SPACE;
  let idx = start % totalBits;
  for (let i = 0; i < totalBits; i++) {
    if (!getBit(bits, idx)) return idx;
    idx += HASH_PROBE_STRIDE;
    if (idx >= totalBits) idx -= totalBits;
  }
  throw new Error("too large");
}
function assignHash(used, baseIdx, hint) {
  if (!getBit(used, baseIdx)) {
    setBit(used, baseIdx);
    hint.value = baseIdx + HASH_PROBE_STRIDE;
    return idxToHash(baseIdx);
  }
  const nextIdx = nextZeroBit(used, hint.value);
  setBit(used, nextIdx);
  hint.value = nextIdx + HASH_PROBE_STRIDE;
  return idxToHash(nextIdx);
}
function lineHashesPure(content) {
  const lines = splitLines(content);
  const hashes = Array.from({ length: lines.length });
  const used = new Uint32Array(BITSET_WORDS);
  const hint = { value: 0 };
  const hashSourceCache = new Map();
  for (let i = 0; i < lines.length; i++) {
    const c = getCached(hashSourceCache, lines[i], hashSource);
    const baseIdx = (xxh32(c) >>> 14) % HASH_SPACE;
    hashes[i] = assignHash(used, baseIdx, hint);
  }
  return hashes;
}
function hashToIndex(hash) {
  let idx = 0;
  for (let j = 0; j < HASH_LEN; j++) {
    const charIdx = ALPH.indexOf(hash[j]);
    if (charIdx < 0) return -1;
    idx = idx * ALPH.length + charIdx;
  }
  return idx;
}
function nearestNew(candidates, target) {
  let lo = 0;
  let hi = candidates.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (candidates[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  const left = lo - 1;
  const right = lo;
  if (
    left >= 0 &&
    (right >= candidates.length ||
      target - candidates[left] <= candidates[right] - target)
  ) {
    return left;
  }
  return right < candidates.length ? right : -1;
}
function mapStableHashes(oldContent, oldHashes, newContent, removedHashes) {
  const oldLines = splitLines(oldContent);
  const newLines = splitLines(newContent);
  const newHashes = Array.from({ length: newLines.length });
  const used = new Uint32Array(BITSET_WORDS);
  const hint = { value: 0 };
  const hashSourceCache = new Map();
  const removed = removedHashes ?? new Set();

  const oldHashIndex = new Map();
  for (let i = 0; i < oldHashes.length; i++) {
    const hash = oldHashes[i];
    oldHashIndex.set(hash, i);
    const idx = hashToIndex(hash);
    if (idx >= 0) setBit(used, idx);
  }

  const removedIndexes = new Set();
  for (const hash of removed) {
    const idx = oldHashIndex.get(hash);
    if (idx !== undefined) removedIndexes.add(idx);
  }

  let spanStart = oldLines.length;
  let spanEnd = -1;
  for (const idx of removedIndexes) {
    if (idx < spanStart) spanStart = idx;
    if (idx > spanEnd) spanEnd = idx;
  }
  const spanLen = spanEnd >= spanStart ? spanEnd - spanStart + 1 : 0;
  const replacementLen = newLines.length - oldLines.length + spanLen;
  const shiftAfterSpan = spanEnd >= spanStart ? replacementLen - spanLen : 0;

  const survivors = [];
  const removedEntries = [];
  for (let i = 0; i < oldLines.length; i++) {
    const entry = { index: i, hash: oldHashes[i] };
    if (removedIndexes.has(i)) removedEntries.push(entry);
    else survivors.push(entry);
  }

  const newByContent = new Map();
  for (let i = 0; i < newLines.length; i++) {
    const key = getCached(hashSourceCache, newLines[i], hashSource);
    const list = newByContent.get(key);
    if (list) list.push(i);
    else newByContent.set(key, [i]);
  }

  const markUsed = (hash) => {
    const idx = hashToIndex(hash);
    if (idx >= 0) {
      setBit(used, idx);
      if (idx + HASH_PROBE_STRIDE > hint.value) hint.value = idx + HASH_PROBE_STRIDE;
    }
  };

  for (const entry of survivors) {
    const candidates = newByContent.get(
      getCached(hashSourceCache, oldLines[entry.index], hashSource),
    );
    if (!candidates || candidates.length === 0) continue;
    const target = entry.index > spanEnd ? entry.index + shiftAfterSpan : entry.index;
    const pos = nearestNew(candidates, target);
    if (pos < 0) continue;
    const newIdx = candidates.splice(pos, 1)[0];
    newHashes[newIdx] = entry.hash;
    markUsed(entry.hash);
  }

  const removedByContent = new Map();
  for (const entry of removedEntries) {
    const key = oldLines[entry.index];
    let queue = removedByContent.get(key);
    if (!queue) {
      queue = { hashes: [], pos: 0 };
      removedByContent.set(key, queue);
    }
    queue.hashes.push(entry.hash);
  }

  for (let i = 0; i < newLines.length; i++) {
    if (newHashes[i]) continue;
    const queue = removedByContent.get(newLines[i]);
    if (!queue || queue.pos >= queue.hashes.length) continue;
    newHashes[i] = queue.hashes[queue.pos];
    queue.pos += 1;
  }

  for (let i = 0; i < newLines.length; i++) {
    if (newHashes[i]) continue;
    const c = getCached(hashSourceCache, newLines[i], hashSource);
    const baseIdx = (xxh32(c) >>> 14) % HASH_SPACE;
    newHashes[i] = assignHash(used, baseIdx, hint);
  }

  return newHashes;
}
// --- end port ---

const xxCases = [
  "",
  "a",
  "abc",
  "hello world",
  "const x = 1;",
  "\tif (a) {",
  "  } ",
  "λ — ünïcødé ✓",
  "x".repeat(600),
  "日本語のテキスト行",
];
const xxVectors = xxCases.map((s) => ({ input: s, h32: xxh32(s) }));

const files = {
  simple: "const a = 1;\nconst b = 2;\nconst c = 3;\n",
  duplicates: "function f() {\n  return 1;\n}\n\nfunction g() {\n  return 1;\n}\n\n",
  emptyFile: "",
  noTrailingNewline: "line one\nline two",
  trailingWhitespace: "alpha   \nbeta\t\ngamma\n",
  unicode: 'const s = "日本語";\nconst t = "λ";\n// ünïcødé\n',
  longLine: "x".repeat(700) + "\n" + "x".repeat(800) + "\ntail\n",
  // 3-byte code points: the 500-byte cap lands mid-character unless the
  // truncation respects code-point boundaries (166 chars = 498 bytes, 167 = 501).
  longMultibyteLine: "あ".repeat(600) + "\n" + "あ".repeat(600) + "い\n" + "tail\n",
  // 4-byte astral code points, and a trailing-whitespace line that canon trims
  // back below the cap.
  astralAndTrim: "🙂".repeat(200) + "\n" + "🙂".repeat(200) + "   \n" + "x\n",
  manyBlanks:
    Array.from({ length: 40 }, (_, i) => (i % 3 === 0 ? "" : `line ${i}`)).join("\n") + "\n",
  // Three same-shaped functions: `}`, `\t}`, `\treturn 0;` and the blank
  // separator each occur three times, which is what a real source file looks
  // like and what the store-carried scenario below drifts on.
  repeatedBlocks: threeBlockFile(),
};
const fileVectors = Object.fromEntries(
  Object.entries(files).map(([k, v]) => [k, { content: v, hashes: lineHashesPure(v) }]),
);

function threeBlockFile() {
  const fn = (name, body) =>
    [
      `export function ${name}() {`,
      "\tif (ready) {",
      `\t\t${body}`,
      "\t}",
      "\treturn 0;",
      "}",
      "",
    ].join("\n");
  return fn("alpha", "go(1);") + "\n" + fn("beta", "go(2);") + "\n" + fn("gamma", "go(3);") + "\n";
}

// --- store-carried anchors (review round 3, finding F1) ---------------------
//
// One edit, run through the SAME call the extension makes after applying a
// mutation: `lineHashes(after, path, {content: before, hashes, removedHashes})`,
// which is `mapStableHashes` plus a `persistSnapshot`. `hashesAfter` is
// therefore literally the anchor list the store hands back on the next read.
const storeScenarios = {
  // An agent prepends a new function. Nothing is removed, so every surviving
  // line keeps its old anchor while its LINE NUMBER moves down by four.
  insertedFunctionAtTop: (() => {
    const before = threeBlockFile();
    const inserted = ["export function inserted() {", "\treturn 9;", "}", ""].join("\n") + "\n";
    const after = inserted + before;
    const hashesBefore = lineHashesPure(before);
    return {
      description:
        "agent prepends a 4-line function; upstream carries every surviving anchor forward",
      before,
      after,
      removedHashes: [],
      hashesBefore,
      hashesAfter: mapStableHashes(before, hashesBefore, after, new Set()),
    };
  })(),
  // Review round 4, finding F1, mechanism (b): content uniqueness does not
  // imply base-index uniqueness. `const value29 = 29;` and
  // `const value298 = 298;` are two DISTINCT, each-unique-in-the-file line
  // contents whose `baseIdx = (xxh32(hashSource) >>> 14) % 238328` collide
  // (found by brute-force search over this exact vendored arithmetic — see
  // `find-collision` in the round-4 PR notes). The first line to be scanned
  // claims the shared base-index slot; the second is probed to a DIFFERENT
  // slot by the identical open-addressing mechanism a literal duplicate line
  // uses, even though its content is not a duplicate of anything else in the
  // file. The edit here (append an unrelated trailer function at the very
  // bottom) does not touch either colliding line or anything before them, so
  // both survive `mapStableHashes` with their pre-edit anchors carried
  // forward unchanged.
  collidingBaseIndexUniqueContent: (() => {
    const collidingLineA = "const value29 = 29;";
    const collidingLineB = "const value298 = 298;";
    const before =
      [collidingLineA, collidingLineB, "", "function noop() {}", ""].join("\n") + "\n";
    const after = before + "function trailer() {\n\treturn 1;\n}\n";
    const hashesBefore = lineHashesPure(before);
    return {
      description:
        "two distinct, each-unique-in-the-file line contents collide on baseIdx; the " +
        "second is probed to a different slot even though it has no duplicate content, " +
        "and an unrelated trailing append does not disturb either anchor",
      before,
      after,
      removedHashes: [],
      hashesBefore,
      hashesAfter: mapStableHashes(before, hashesBefore, after, new Set()),
    };
  })(),
};

